logger = logging.getLogger(__name__)


def is_transaction_description_suspicious(description: str) -> bool:
    """
    Analyze a transaction description with OpenAI and return whether it may be suspicious.

    This helper expects the OpenAI API key to be available in the
    OPENAI_API_KEY environment variable.
    """
    if not description or not description.strip():
        return False

    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        logger.warning("OPENAI_API_KEY is not set; treating description as not suspicious")
        return False

    payload = {
        "model": "gpt-4o",
        "temperature": 0,
        "messages": [
            {
                "role": "system",
                "content": (
                    "You are a fraud detection helper. "
                    "Reply with only 'true' if the transaction description seems suspicious, "
                    "or only 'false' if it does not."
                ),
            },
            {
                "role": "user",
                "content": f"Transaction description: {description}",
            },
        ],
    }

    req = request.Request(
        "https://api.openai.com/v1/chat/completions",
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
        method="POST",
    )

    try:
        with request.urlopen(req, timeout=15) as response:
            body = json.loads(response.read().decode("utf-8"))
    except error.URLError as exc:
        logger.warning("OpenAI fraud check failed: %s", exc)
        return False
    except Exception as exc:
        logger.warning("Unexpected OpenAI fraud check error: %s", exc)
        return False

    content = (
        body.get("choices", [{}])[0]
        .get("message", {})
        .get("content", "")
        .strip()
        .lower()
    )
    return content == "true"


